181	// Device existence and permission are enforced after shape validation, and a
182	// failure exposes no change content.
183	func TestQueryChangesHTTPGate(t *testing.T) {
184		h, _ := newTestHandler(t)
185		registerDevice(t, h, "dev")
186		postRawChanges(t, h, "doc1", "dev", `[{"id":"a","payload":1}]`)
