261	// Method and path shape: only POST at the exact .../changes/query location is
262	// accepted; every other verb or shape is a JSON 400, never a redirect.
263	func TestQueryChangesHTTPMethodAndPath(t *testing.T) {
264		h, _ := newTestHandler(t)
265	
266		cases := []struct {
267			method string
268			path   string
269		}{
270			{http.MethodGet, "/v1/documents/doc1/changes/query"},
271			{http.MethodPut, "/v1/documents/doc1/changes/query"},
272			{http.MethodDelete, "/v1/documents/doc1/changes/query"},
273			{http.MethodPost, "/v1/documents/doc1/changes/query/"},
274			{http.MethodPost, "/v1/documents/doc1/changes/query/extra"},
275			{http.MethodPost, "/v1/documents/doc1/changes/queryextra"},
276			{http.MethodPost, "/v1/documents//changes/query"},
277			{http.MethodPost, "/v1/documents/doc1/changesx/query"},
278		}
279		for _, tc := range cases {
280			t.Run(tc.method+" "+tc.path, func(t *testing.T) {
281				r := httptest.NewRequest(tc.method, tc.path, strings.NewReader(`{"deviceId":"dev","ids":["a"]}`))
282				r.Header.Set("Content-Type", "application/json")
283				w := httptest.NewRecorder()
284				h.ServeHTTP(w, r)
285				if w.Code != http.StatusBadRequest {
286					t.Fatalf("status = %d want 400 body = %s", w.Code, w.Body.String())
287				}
288				if ct := w.Header().Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
289					t.Fatalf("content type = %q, want JSON", ct)
290				}
291				if loc := w.Header().Get("Location"); loc != "" {
292					t.Fatalf("failure redirected to %q", loc)
293				}
294			})
295		}
296	}
297	
298	// A document literally named "query" keeps its ordinary change routes; the
299	// query keyword is only recognized in the terminal subresource position.
300	func TestQueryChangesHTTPDocumentNamedQuery(t *testing.T) {
301		h, _ := newTestHandler(t)
302		registerDevice(t, h, "dev")
303		postRawChanges(t, h, "query", "dev", `[{"id":"z","payload":1}]`)
304	
305		// Ordinary paged read on the document named "query".
306		w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/query/changes")
307		if w.Code != http.StatusOK || !strings.Contains(w.Body.String(), `"id":"z"`) {
308			t.Fatalf("paged read on doc named query = %d %s", w.Code, w.Body.String())
309		}
310		// The lookup subresource of that document answers normally too.
311		w = queryChanges(t, h, "query", `{"deviceId":"dev","ids":["z"]}`)
312		if w.Code != http.StatusOK || !strings.Contains(w.Body.String(), `"status":"found"`) {
