package server

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestProbeStatusDelete(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev")
	postDocChanges(t, h, "doc", "dev", 2)
	if w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 1, "state": map[string]any{"s": 1}}); w.Code != 200 {
		t.Fatal(w.Body.String())
	}
