		t.Fatal(w.Body.String())
	}
	// Delete the whole document.
	r := httptest.NewRequest(http.MethodDelete, "/v1/documents/doc?deviceId=dev", nil)
	w := httptest.NewRecorder()
	h.ServeHTTP(w, r)
	if w.Code != 200 {
		t.Fatalf("delete = %d %s", w.Code, w.Body.String())
	}
	got := getChangeStatus(t, h, "doc", "deviceId=dev")
	t.Logf("after delete: %d %q", got.Code, got.Body.String())
	if got.Code != 200 || got.Body.String() != `{"onlineCount":0,"boundary":0,"maxCursor":0,"trimmedCount":0}`+"\n" {
		t.Fatalf("post-delete status mismatch")
	}
	// Deregister the device -> 404.
	if err := deregisterHelper(h, "dev"); err != nil {
		t.Fatal(err)
	}
	got = getChangeStatus(t, h, "doc", "deviceId=dev")
	t.Logf("after deregister: %d %q", got.Code, got.Body.String())
	if got.Code != 404 {
		t.Fatalf("want 404")
	}
}
