func deregisterHelper(h http.Handler, device string) error {
	r := httptest.NewRequest(http.MethodDelete, "/v1/devices/"+device, nil)
	w := httptest.NewRecorder()
	h.ServeHTTP(w, r)
	if w.Code != 200 {
		return &probeErr{w.Body.String()}
	}
	return nil
}

type probeErr struct{ msg string }
func (e *probeErr) Error() string { return e.msg }
